/**
 * The answers Val Build sends, for tests and stories: the JSON beside this
 * file is generated by valbuild/home's `tierStates.test.ts` and copied here
 * unchanged (see README.md). This only gathers it, and wraps an `access-*`
 * `limits` in the whole `/access` body as valbuild/home's route sends it.
 */
import accessFreeAtLimit from "./access-free-at-limit.json";
import accessFreeWarn from "./access-free-warn.json";
import accessFree from "./access-free.json";
import accessHostedConverted from "./access-hosted-converted.json";
import accessHostedTrialOver from "./access-hosted-trial-over.json";
import accessHostedTrialPublishesUsed from "./access-hosted-trial-publishes-used.json";
import accessHostedTrialWithCard from "./access-hosted-trial-with-card.json";
import accessHostedTrial from "./access-hosted-trial.json";
import accessHostedUsageWarn from "./access-hosted-usage-warn.json";
import accessProPaymentFailed from "./access-pro-payment-failed.json";
import accessPro from "./access-pro.json";
import accessSponsored from "./access-sponsored.json";
import refusedLimitChanges from "./refused-limit-changes.json";
import refusedPaymentFailed from "./refused-payment-failed.json";
import refusedPlanRemoteFiles from "./refused-plan-remote-files.json";
import refusedReadOnlyPaymentFailed from "./refused-read-only-payment-failed.json";
import refusedTrialOver from "./refused-trial-over.json";
import refusedTrialPublishes from "./refused-trial-publishes.json";
import refusedUsageStorage from "./refused-usage-storage.json";

export const ACCESS_FIXTURES = {
  "access-free-at-limit": accessFreeAtLimit,
  "access-free-warn": accessFreeWarn,
  "access-free": accessFree,
  "access-hosted-converted": accessHostedConverted,
  "access-hosted-trial-over": accessHostedTrialOver,
  "access-hosted-trial-publishes-used": accessHostedTrialPublishesUsed,
  "access-hosted-trial-with-card": accessHostedTrialWithCard,
  "access-hosted-trial": accessHostedTrial,
  "access-hosted-usage-warn": accessHostedUsageWarn,
  "access-pro-payment-failed": accessProPaymentFailed,
  "access-pro": accessPro,
  "access-sponsored": accessSponsored,
};

export const REFUSED_FIXTURES = {
  "refused-limit-changes": refusedLimitChanges,
  "refused-payment-failed": refusedPaymentFailed,
  "refused-plan-remote-files": refusedPlanRemoteFiles,
  "refused-read-only-payment-failed": refusedReadOnlyPaymentFailed,
  "refused-trial-over": refusedTrialOver,
  "refused-trial-publishes": refusedTrialPublishes,
  "refused-usage-storage": refusedUsageStorage,
};

export type AccessFixture = keyof typeof ACCESS_FIXTURES;

/** The organization in the fixtures, and its links. */
export const BILLING_URL = "https://admin.val.build/~/acme?section=billing";
export const PROJECT_URL = "https://admin.val.build/~/acme/website";

export const OWNERS = [
  { name: "Ada Lovelace", email: "ada@acme.com" },
  { name: "Ole Nordmann", email: "ole@acme.com" },
];

/**
 * The whole `/access` body for a state, as an owner (`canFix`) or anyone
 * else sees it: the organization's half (read-only for a failed payment),
 * `limits`, and who can fix it (valbuild/home's `studio/routes.ts`).
 */
export function studioAccessBody(
  state: AccessFixture,
  who: "owner" | "editor",
): Record<string, unknown> {
  const plan =
    state === "access-pro-payment-failed"
      ? {
          access: "read-only",
          reason: "payment-failed",
          billingUrl: BILLING_URL,
        }
      : { access: "edit" };
  return {
    ...plan,
    limits: ACCESS_FIXTURES[state],
    org: "acme",
    canFix: who === "owner",
    owners: OWNERS,
    billingUrl: BILLING_URL,
    projectUrl: PROJECT_URL,
  };
}
